def balanced(s):
    """Return True if every (, [ and { in s is closed in the correct order.

    Text inside double-quoted strings is ignored. Inside a string, a backslash
    escapes the next character. An unterminated string makes the input unbalanced.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    in_str = False
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_str = False
        else:
            if c == '"':
                in_str = True
            elif c in '([{':
                stack.append(c)
            elif c in pairs:
                if not stack or stack[-1] != pairs[c]:
                    return False
                stack.pop()
        i += 1
    if in_str:
        return False
    return not stack
